#!/usr/bin/env python3
"""
gen_nmake_makes.py — генерирует NMAKE-макфайл из VC6 .dsp проекта.

Читает список SOURCE= и флаги ADD CPP / RSC / LIB32 / LINK32 выбранной
конфигурации, печатает макфайл для `nmake /f <out>.mak` под cl.exe (VC6).

Пример:
  python gen_nmake_makes.py --dsp R3Engine/R3Engine.dsp \
      --cfg "R3Engine - Win32 Client Debug" \
      --extra-include "<dxsdk_include>" \
      --out ci_engine.mak
"""
import argparse
import os
import re


def parse_dsp(path, cfg_name):
    txt = open(path, "r", errors="ignore").read().replace("\r\n", "\n").replace("\r", "\n")

    sources = [m.group(1).strip().strip('"') for m in re.finditer(r"SOURCE=(.*)", txt)]
    seen, cpps = set(), []
    for s in sorted(set(sources)):
        if s.lower().endswith(".cpp") and s not in seen:
            seen.add(s)
            cpps.append(s)
    rcfile = None
    for s in sorted(set(sources)):
        if s.lower().endswith(".rc"):
            rcfile = s
            break

    blocks, cur, buf = {}, None, []
    for line in txt.split("\n"):
        m = re.match(r'!IF\s+"\$\(CFG\)" == "(.+)"', line)
        m2 = re.match(r'!ELSEIF\s+"\$\(CFG\)" == "(.+)"', line)
        if m or m2:
            if cur:
                blocks[cur] = buf
            cur, buf = (m or m2).group(1), []
        elif re.match(r"!ENDIF", line):
            if cur:
                blocks[cur] = buf
            cur, buf = None, []
        elif cur is not None:
            buf.append(line)
    if cur:
        blocks[cur] = buf
    if cfg_name not in blocks:
        raise SystemExit(f"Конфигурация '{cfg_name}' не найдена. Доступные: {list(blocks)}")

    blk = "\n".join(blocks[cfg_name])

    def last(pattern):
        ms = re.findall(pattern, blk, re.M)
        return ms[-1].strip() if ms else ""

    return {
        "sources": cpps,
        "rc": rcfile,
        "cpp_flags": last(r"^# ADD CPP (.*)$"),
        "rsc_flags": last(r"^# ADD RSC (.*)$"),
        "lib32": last(r"^# ADD LIB32 (.*)$"),
        "link32": last(r"^# ADD LINK32 (.*)$"),
        "intermediate_dir": last(r'^# PROP Intermediate_Dir "([^"]+)"'),
        "output_dir": last(r'^# PROP Output_Dir "([^"]+)"'),
    }


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dsp", required=True)
    ap.add_argument("--cfg", required=True)
    ap.add_argument("--extra-include", action="append", default=[])
    ap.add_argument("--extra-libpath", action="append", default=[])
    ap.add_argument("--define", action="append", default=[])
    ap.add_argument("--out", required=True)
    args = ap.parse_args()

    d = parse_dsp(args.dsp, args.cfg)
    projdir = os.path.dirname(args.dsp) or "."

    extra_inc = " ".join('/I"%s"' % p for p in args.extra_include)
    extra_lp = " ".join('/LIBPATH:"%s"' % p for p in args.extra_libpath)
    defines = " ".join('/D"%s"' % x for x in args.define)

    cpp_flags = d["cpp_flags"].replace("/YX", "").replace("/FR", "").replace("/Gm", "")
    cpp_flags = (cpp_flags + " " + extra_inc + " " + defines).replace("  ", " ").strip()

    obj_dir = d["intermediate_dir"] or "obj_ci"
    out_dir = d["output_dir"] or "."

    # cl.exe вызывается из корня проекта; /Fo"$@" требует, чтобы obj-файлы
    # складывались в OBJDIR с плоскими именами (иначе каталоги могут не существовать)
    objs = " ".join(
        os.path.join(obj_dir, os.path.basename(os.path.splitext(s.replace("\\", "/"))[0]) + ".obj")
        for s in d["sources"]
    )

    is_lib = bool(d["lib32"]) and not d["link32"]
    m = re.search(r'/out:"([^"]+)"', d["lib32"] if is_lib else d["link32"])
    target = m.group(1) if m else ("engine.lib" if is_lib else "client.bin")

    L = []
    a = L.append
    a("# Generated by .github/scripts/gen_nmake_makes.py — DO NOT EDIT")
    a("# Project: %s | Config: %s" % (args.dsp, args.cfg))
    a("")
    a("CPPFLAGS=%s" % cpp_flags)
    a("OBJDIR=%s" % obj_dir)
    a("OUTDIR=%s" % out_dir)
    a("TARGET=%s" % target)
    a("OBJS=%s" % objs)
    if d["rc"]:
        res = os.path.splitext(d["rc"])[0] + ".res"
        a("RES=%s" % res)
        a("OBJS=$(OBJS) $(RES)")
    a("")
    a("all: $(TARGET)")
    a("")
    if is_lib:
        libflags = re.sub(r'/out:"[^"]+"', "", d["lib32"]).strip()
        a("$(TARGET): $(OBJS)")
        a("\t-if not exist \"$(OBJDIR)\" mkdir \"$(OBJDIR)\"")
        a("\t-if not exist \"$(OUTDIR)\" mkdir \"$(OUTDIR)\"")
        a("\tlib.exe %s /out:\"$@\" $(OBJS)" % libflags)
    else:
        linkflags = re.sub(r'/out:"[^"]+"', "", d["link32"]).strip()
        linkflags = (linkflags + " " + extra_lp).strip()
        a("$(TARGET): $(OBJS)")
        a("\t-if not exist \"$(OBJDIR)\" mkdir \"$(OBJDIR)\"")
        a("\t-if not exist \"$(OUTDIR)\" mkdir \"$(OUTDIR)\"")
        a("\tlink.exe %s /out:\"$@\" $(OBJS)" % linkflags)
    a("")
    a(".cpp.obj:")
    a("\t-if not exist \"$(OBJDIR)\" mkdir \"$(OBJDIR)\"")
    a("\tcl.exe $(CPPFLAGS) /c /Fo\"$(OBJDIR)/$(@F)\" $<")
    if d["rc"]:
        a("")
        a(".rc.res:")
        a("\trc.exe %s /fo \"$@\" $<" % d["rsc_flags"])
    a("")
    a("clean:")
    a("\t-if exist \"$(OBJDIR)\" rmdir /s /q \"$(OBJDIR)\"")
    a("\t-del /q \"$(TARGET)\"")
    a("")

    with open(args.out, "w", newline="\r\n") as f:
        f.write("\n".join(L))
    print("[gen_nmake] wrote %s (%s, %d cpp)%s" % (
        args.out, "static lib" if is_lib else "exe/dll", len(d["sources"]),
        " + rc" if d["rc"] else ""))


if __name__ == "__main__":
    main()
